-- Generated by scripts/letters.ts from i18n/esES/letters/: edit those, not this file.
-- letterTexts[id] = { greeting, body = { paragraph, ... }, signoff (its lines), ps = { paragraph, ... } }
local _, ns = ...
ns.letterTexts = {
  [1] = { greeting = "$N,", body = { "I knew Edwin VanCleef's name long before I knew his crimes. There are walls in Stormwind he raised with his own hands. I am glad it is done, and I did not enjoy asking it of you.", "Furlbrow wants to take his family home. I had to tell him not yet. He wanted a day he could mark down, and I could not give him one. We still need men on the roads.", "The night watch passed without an alarm. I do not trust it yet, and I have told the men not to.", "You have my thanks, and the militia's. I wanted you to hear it from me." }, signoff = "Gryan Stoutmantle\nThe People's Militia" },
  [2] = { greeting = "Dear $N,", body = { "The memorial is finished, I am told, and Grand Mason Marblesten is pleased with the Alterac granite you brought him. I asked our King what the war would cost us. He has answered me in granite. I asked the mason only whether Sully's name is cut deep enough to stay legible when the stone begins to wear. Perhaps that is a foolish question. It mattered to me.", "I have put his letter away several times. Then one of the boys asks what his father said, and I take it out again. Little Edgar knows where I pause now, and waits for me there before I turn the page.", "There are things in it Sully never said to me when he was home. 'Tis strange to hear them now, in his own hand. I should have liked to answer him.", "Thank you for bringing it back to us. I could not have borne to lose that too." }, signoff = "With gratitude,\nSara Balloo" },
  [3] = { greeting = "$C,", body = { "Ramstein's head is on the wall. The hounds will eat living rot without complaint. They will not eat beneath that head. I have moved their bowls.", "I hunted Ramstein for months before it fled into Stratholme. Having it here has done little for the state of the farm. I did not expect it to. I wanted the thing dead, and you saw to it.", "You came to my stead an imbecile. You are now one of my champions. I put that in writing because you would not believe it otherwise. Try not to let it swell what passes for your head.", "There. You have had it." }, signoff = "Nathanos" },
  [4] = { greeting = "$N,", body = { "My mother was glad to hear that you had stood before Cairne, young one, and her first thought was whether you had eaten before the climb. I could not tell her, and she feels a chief should know such things.", "She still walks to the well for her own water. When I offered to carry the pitcher, she asked if a chief had nothing better to do, and when I said that you had carried it for her once, she told me I could have fetched the water in the time it took me to say so.", "Baine sent word of you, and I read it to the others by the fire. The little ones made me read it twice, and they have talked of the Rites every evening since.", "My mother says this letter has too many corners, like my carvings. I told her you would read it anyway." }, signoff = "Walk with the Earthmother,\nChief Hawkwind" },
  [5] = { greeting = "Kid,", body = { "The lens is fitted, the telescope works, and the boots are back on the shelves. Customers quit asking where they were. Best silence I ever paid for.", "Listen. Dizzywig filed your pay under freight. I made him change it. Freight doesn't walk into a pirate camp and walk out with the right crates. By my books, that leaves me owing you the difference. So Dizzywig is fixing the books. Not the difference, kid. The books.", "Everybody in Ratchet promises. Ninety-nine in a hundred come back with a story about why they couldn't. You came back with my boots. In my line, that's rarer than gold, and I'd know." }, signoff = "Gazlowe", ps = { "P.S. The pirates are back on the beach. I've sent them an invoice." } },
  [6] = { greeting = "My dear $N!", body = { "Bangalash! The whole camp is still shouting about him over supper! Sir Erlgadin swears his panther was the harder quarry, and Ajeck won't hear a word of it. I have moved the kettle twice to save it from their demonstrations.", "Erlgadin, Ajeck and I all have a great deal to say about a tiger you brought down! I had my sights on that white devil for a very long time, old chap, and I have earned a word or two on the subject.", "Barnil read my account of the hunt and asked where you came into it. A fair question! I'm afraid I got quite carried away with my own attempts and forgot you entirely. Right-o, I have put you back where you belong.", "Bloody well done! Cheers to you, I say! Cheers!" }, signoff = "Hemet Nesingwary" },
  [7] = { greeting = "Hello from the cave, $N!", body = { "I'm still right where you found me. I feel completely better, I promise. Well, mostly. There are still a great many Webwood spiders between me and the rest of Shadowglen, and a sensible elf waits until they look busy.", "Dirania sends word that I'm fit to walk home. She also reminds me, each time, that she always warned me about those spiders. Well, she did.", "I used to visit her at the same time every day. Now she knows exactly where I am at every hour, and I think she prefers it.", "I'm always getting into trouble, and somebody always gets me out of it. Usually it's Dirania. This time it was you, with five minutes to do it in. Thank you." }, signoff = "Your friend,\nIverron" },
  [8] = { greeting = "$N,", body = { "The fruit you found is the most interesting thing in my camp. I keep it wrapped, well away from the soil, until I understand what passed between them. Was the fault in the fruit, or in the earth of Teldrassil? I would rather it were the fruit.", "The timberling seeds are in the special soil, with the rare earth you carried from Dolanaar, and I look in on them more often than is useful. I am told a watched seed never grows. I have found that neither true nor false.", "What I know: the plant that bore the fruit is a stranger here. Perhaps its seed was carried from very far off. What I do not know: nearly everything else. It is a wonderful position to be in.", "You have a good eye, $N. Thank you for lending it to me." }, signoff = "Respectfully,\nDenalan" },
  [9] = { greeting = "$N!", body = { "I did it!! I drank every drop and walked right out past the house, and nobody saw a thing. Not one thing! I could hear my own feet, and I was sure the whole vineyard could too.", "Tommy Joe was at the river, just where he always is. Of course he couldn't see me either, so I had to say his name, and he jumped so high I thought he'd go in. Then he laughed, and then I did, and we talked until I could see my own hands again. I ran all the way home.", "I know it was wicked to deceive my family. I would do it again in a heartbeat!", "I can't even thank Mr. Pestle or Gramma Stonefield, because I'm not supposed to know either of them!", "You carried my letter to Tommy Joe. This one is for you." }, signoff = "All my love (but not that kind!),\nM." },
  [10] = { greeting = "Dear $N,", body = { "The necklace is back where it belongs. I sleep in it. Let the kobolds try.", "That Billy Maclure tells anyone who'll stand still that my pie was the best he ever ate. Of course it was. That's not the point. The point is he took my necklace and got pie for his trouble, and now half the forest knows my pie better than my name.", "I gave you my husband's gloves because they were doing nobody any good on the hook by the door. He always said they were lucky, and then he went off on his last campaign without them. I've looked at that hook a long while. Better they go out the door with somebody.", "Thank you, dear. You did warm an old widow's heart, though I'll deny it to any Maclure who asks." }, signoff = "Auntie Bernice", ps = { "P.S. I didn't put anything in Billy's pie. I thought about it." } },
  [11] = { greeting = "Hail, $N!", body = { "My brother says the Shimmer Stout puts a shine in your eyes and he can see in the dark. Mountaineer Kadrell sent word from Thelsamar that it lightens the limbs and he feels like he can fly. A brewer could live on words like that, and I nearly have. Thank you for carrying it to them, $glad:lass;.", "Here's the trouble. It isn't perfect. A stout that makes a dwarf feel he can fly is a fine stout. A perfect stout keeps his boots on the ground and makes him glad of it. The shimmerweed is the right note. It's the malt underneath that's wrong, too sweet or not dark enough, and I've three small batches going to find out.", "Brewing's in my blood, and blood is patient. I'll get there." }, signoff = "Rejold Barleybrew" },
  [12] = { greeting = "$N,", body = { "Lumber: short. Peons: asleep. Two under the same tree, one on the lumber pile, and one standing up. I didn't know they could do that.", "They remember you, though. Word went round that you were loose in the valley with my blackjack. Now when one hears footsteps he's on his feet and swinging an axe before his eyes are open. Doesn't last. Better than nothing.", "They ask if you're coming back. I tell them yes. I don't tell them when.", "Good work. Thanks for the help." }, signoff = "Thazz'ril\nForeman" },
  [13] = { greeting = "$N,", body = { "The night you brought me the head, I did not sleep. I sat by the water and listened. No drums came over from the isles. Behind me the village slept, all of it, the way it used to. I wanted to hear that.", "From the shore you can see the Echo Isles. I still know which beach was mine. They are not ours. I watch them anyway.", "Some of those you fought were Darkspear, before the hex. Do not grieve them. That is ours to do, and we have done it." }, signoff = "Gadrin" },
  [14] = { greeting = "Young $N,", body = { "The beasts drink at the Winterhoof well again, as eagerly as on the day it was cleansed. I have watched the plainstriders bend to it, and the wolves come down to it after them, and each time I have thought that they drink from water their own kind helped to make pure. They do not know it, but the land does, and so do I.", "Every totem asked something of the beasts of Mulgore, down to the alphas' teeth, and my spirit is heavy for them still, and proud. They did not choose to give, and it was you who carried their gift to the wells.", "When the wind comes down from the north, I hear the spirits speak of you." }, signoff = "May the spirits guide you,\nMull Thunderhorn" },
  [15] = { greeting = "$N,", body = { "I write to acknowledge receipt of Deathguard Linnea's report, delivered by your hand and without delay. In Brill, promptness is rare enough to be remarked upon.", "The report said what she told you. The Bulwark holds the greater part of the Scourge, and some slip through. I have filed it with the others that say the same.", "The graves by Garren's Haunt aren't safe, but the dead in them remain dead, which was the object. They were spared what was done to us. I find I have a personal interest in keeping it so, and your work among the Rot Hides served it. The Apothecaries have the ichor. They have told me nothing, which in my experience means they are pleased.", "The Lich King and his minions are ceaseless in their assaults. He will not take us again." }, signoff = "With my official thanks,\nMagistrate Sevren" },
  [16] = { greeting = "$N,", body = { "Do you still feel it, the hum near the standing stones? Yes? Good. Then it took, and you will feel it again in many places.", "Ley lines used to live in old books. Now they come up through the grass to meet us. Gift or warning, it is knowledge, and I mean to have all of it before anyone else decides what I may know.", "Rorian gave you your relic and told you the winds of home would be with you wherever you travel. Rorian believes that, and it is a kind thing to believe. I prefer what I can measure.", "These are hard times for the shen'dorei, and I know which I want first: knowledge, then power." }, signoff = "Make the unknown known,\nFalorne Fallwind" },
  [17] = { greeting = "$N,", body = { "A gift from the spirits is still a muscle, and a muscle left alone goes soft. Use your skysight on the road, at the inn, in the rain. Most days you will see nothing worth seeing. Use it anyway.", "I keep mine open a little every evening, here in the village, before I sleep. Some evenings I catch a word or two, faint as a voice through a wall. Some evenings, nothing. I have learned not to resent the quiet ones. They are part of the practice too.", "I write down what I catch, even when it makes no sense. Especially then. The spirits do not repeat themselves for our convenience.", "We will need everyone who can listen." }, signoff = "Patience,\nVentaari Brightwish" },
  [18] = { greeting = "$N,", body = { "I sent Belathaan to the Shrine of Akir because logic told me to. Talk costs less than blood, and peace less than war. Every line of that reasoning was sound. The cult answered it with a box. I have gone over my arguments many times since, looking for the error, and I can only find it in my estimate of the people I sent him to.", "The Windshapers were right. Writing that down is worse than saying it.", "The charms you brought me are locked away. I look at them less than I did. I have not forgotten who brought them.", "The cult weighed our prudence and called it weakness. That was an estimate too, and theirs is the worse one." }, signoff = "Elaadrin Evengale\nSupreme Magister of the High Order" },
  [19] = { greeting = "$N,", body = { "I owe you a better answer than the one I gave you when you brought me the charms. \"A trying day\" was not it.", "Windshapers trade blood for blood. I have said it all my life, and I meant it when I sent you north. I still mean it. The novices we found in the Highlands were ours, and someone will answer for every one of them.", "But I had also sent you after Belathaan, to frighten him, and he never came back from that road. I told you it was not your fault. That was true. I did not say whose it was, because I have not decided. Elaadrin's, for sending him. The cult's, for killing him. Mine, for wanting him afraid. His mother was one of us.", "We do not forgive and we do not forget. I will not forget him either." }, signoff = "Ayessa Dawnsinger\nGrand Skyseer of the Windshapers" },
  [20] = { greeting = "$N,", body = { "The Dam still stands! I go down to the base every morning and every evening to look, and it still stands, and I thank the stars each time. Oh heavens, I hope you never learn what that powder would have done wet. I worked it out on paper twice, and then I stopped working it out!!", "The security detail is still at the Alliance Front, and my best inspector with them. So it is me, whoever the mountaineers can spare, and the water. I knock on every barrel I pass now. Every single one.", "You came when no one else did, and you stirred that keg as if it were soup. I don't know whether that was courage or ignorance, and I am grateful for either!", "The Dam is safe, for the time being at least, and so is everyone below it." }, signoff = "Yours in some haste,\nHinderweir VII\nChief Engineer, Stonewrought Dam" },
  [21] = { greeting = "$N,", body = { "For once, a letter from me that you need not carry anywhere.", "I have read the three replies you brought me more often than a magistrate ought to read anything. Stormwind will send reinforcements when the King gives the word. Westfall has no men to spare and its own dead to bury. Darkshire cannot send its Night Watch past the edge of its own forest. Each answer is reasonable. Together they make no sense at all.", "Lakeshire holds, for now. There is treachery somewhere in all this, and I mean to learn whose. Bah. I should not ponder aloud, not even on paper.", "You walked a long way for a township that owed you nothing, and each time you came back with the truth, even when the truth was no. Thank you." }, signoff = "Magistrate Solomon\nLakeshire" },
  [22] = { greeting = "$N,", body = { "Hollee tells me that you are the one who walked me out of the dig, and that I was not, as I believed at the time, simply taking a stroll. She says there were golems. I recall a very interesting layer of sediment.", "She also tells me my fossil has been to Darnassus and then to Menethil Harbor, which is more travel than I have done in years, and that a fellow named Flagongut has it now, along with some stone of his own. Splendid! I hope he writes. I hope he writes to me, that is, and not to Hollee, though Hollee does seem to receive everything.", "I have been looking for my stone brush. I mention it only because I have been looking for it the whole time I was writing this, and it seemed rude not to say so." }, signoff = "With thanks, and I think apologies,\nProspector Remtravel" },
  [23] = { greeting = "$N,", body = { "The NG-5 arrived in perfect condition, which is to say it did not arrive all over you, and I count that a success for everyone involved!", "Lomac is the finest chemist I have ever been shouted at by. If he said hello, he meant it. If he said anything else, he also meant it, only less.", "Everything is in place. I won't tell you the plan, partly because a plan told is a plan spoiled, partly because it changes every time I look at it. It involves wagons. It involves dynamite, which is not as dangerous as everyone thinks. It involves magic, mixtures and mechanisms all working together, which is the whole point of the Assembly and, frankly, of me.", "The night elves still look at me as if I might go off. That's fair. Showing them a gnome can help save their forests is my goal, nay, my DUTY!" }, signoff = "Gaxim Rustfizzle\nEnlightened Assembly of Arcanology, Alchemy and Engineering Sciences" },
  [24] = { greeting = "$N,", body = { "The time for mourning has come, as I said it would, and it keeps no hour I would choose. I wrote to Teronis's family. It was the shortest letter I have ever written, and it took me all night.", "You found him, and you found what he died looking for. It was more than I dared hope, and it is not enough.", "The furbolg were not always our enemy. When I was young, I never once drew a bow on one. Now I have sent you down the road to their camps and called it defense, and it was. I only want it written somewhere that I remember the quieter time." }, signoff = "Elune keep you,\nRaene Wolfrunner" },
  [25] = { greeting = "$N,", body = { "I have told the high priestess. What passed between us I will keep. I will say only that I took the long way back to the bunkhouse.", "Velinde's chest is still in the bunkhouse. I find I cannot have it emptied. The Sentinels believed she had her own reasons for leaving and would come back when she chose. I believed it too, and said so to you. I would rather have been wrong about almost anything else.", "It unsettles me that the Scythe of Elune has fallen out of her servants' hands.", "You followed her across half the world on the word of a book that writes itself. Few would have. I owe you my thanks, in no small amount." }, signoff = "Thyn'tel Bladeweaver" },
  [26] = { greeting = "$C,", body = { "Forgive my temper when you came to see me. It rivaled a rabid kodo bull's, and you had done nothing to earn it. The fault was mine. I sent travelers below the city without a thought for who else might follow them, and two friends paid for my carelessness. Thrall's do-gooders, whoever they were. I would give a great deal for their names.", "I am tidying what I can below. Our friends in the Barrens and in the forest have begun their own work.", "You came to me at the right moment, wearing the right mark. I do not forget that. In a city where so few are what they seem, it is a comfort to know one who is." }, signoff = "A friend in the Cleft" },
  [27] = { greeting = "$N,", body = { "I have drawn what I could from the Pyrewood shackles you brought me. It was not enough. I suspected as much, and I believe I said so. A limited sample is a limited sample.", "Still, I understand the remedy now, or most of it, and the more I understand it, the less I think of the man who cast it. The Kirin Tor let him into their halls. I have stopped asking how.", "In Pyrewood they are still men and women by day, and still something else when the sun goes down. Arugal did that to a whole village with a spell any apprentice would be ashamed to sign. That is what I find hardest to forgive. Not the curse. The workmanship.", "It will take longer than I thought. Everything to do with Arugal takes longer than I think. It may be his one talent.", "Cheers to you, $N." }, signoff = "Dalar Dawnweaver\nThe Sepulcher" },
  [28] = { greeting = "$N,", body = { "Before you left for Fenris Isle, I wrote two reports for the Undercity. One said that Thule Ravenclaw was dead. The other said that I had sent you after him and you had not come back. A commander should be ready for either. I burned the second the day you came back with his head.", "Renferrel tells me the energies released when Thule fell were felt as far as the Sepulcher. He is right. I felt it myself, and I knew what you had done before anyone told me.", "The Scourge are not finished in Silverpine. The rot hides still hold the island, and they will not leave it for one dead mage. But they have lost ground, and they lost it to one of ours.", "Your value to us grows." }, signoff = "High Executor Hadrec\nThe Sepulcher" },
  [29] = { greeting = "$N,", body = { "I am no hand at letters. She was the one with words.", "She held three quilboar off by herself. When more came, I led some away and told myself that was the brave part. I don't tell myself that now.", "The druid who found me on the road told me to rest. I rested. Then I went back to the camp where we were separated, and I killed every quilboar I found there. That did not help either.", "You found her when I couldn't. I don't know what you saw there, and I am not asking.", "Thank you, $C." }, signoff = "Mankrik" },
  [30] = { greeting = "$N,", body = { "I slept through the night. All of it, from dark to the first light on the Rise, and I woke with my hands open. I had forgotten that sleep could be so plain.", "When the elder left the dreaming, I stayed, because someone had to see their faces. I did. Then I could not stop seeing them. Four faces, every night, turning toward me as if they knew me. I used to wake with my fists closed and my teeth aching. They do not come any more.", "They were druids once. Their order meant to heal the Barrens. I think about that more than I would like. It would be easier to hate them if they had always been what they became.", "The land still dreams, and badly. That was never one night's work. But my dreams belong to me again, and you are the one who took them back." }, signoff = "Nara Wildmane" },
  [31] = { greeting = "$N,", body = { "The bunkers held. Krom'zar came all the way from Desolace for his vengeance, and what he found was you.", "Barak, Verog, Hezrul, and then Krom'zar. I have fought centaur most of my life, and I have never seen four of their leaders fall to one fighter. A centaur with the wit to lead is rare, and they are the dangerous ones. You took the dangerous ones.", "The Kolkar will come again. They always have. When they do, they will come telling each other about you, and I hope they tell it badly.", "Stand tall, $N." }, signoff = "Regthar Deathgate" },
  [32] = { greeting = "$R,", body = { "Mangletooth writes. <snort> Hands not made for pens. Read it anyway.", "Mangletooth saw you run, from the cage. You ran with zhevra. The wind was jealous, like Mangletooth said. <snort> Agamaggan's spirit still answers Mangletooth, through bars and all. No cage stops that. Remember.", "Bristleback weaker now, thanks to you and to Mangletooth. And still the Razormane do not come. Mangletooth counted the days. Then Mangletooth stopped counting. <snort>", "The touch of the shards. Long time since Mangletooth held one. You do not know what it is, to have your power cut away from you. Mangletooth hopes you never know.", "Mangletooth is no fool. Mangletooth is grateful. Both. <snort>" }, signoff = "Mangletooth\nCamp Taurajo" },
  [33] = { greeting = "$N,", body = { "The goblins still log the Crag. On a west wind I can smell their smoke from here on the border. Two broken machines will not teach them, and I never thought they would.", "But most of the wailing has stopped. Not the grief, the wailing. The spirits are hurt, still, and they have every right to be. They are no longer blind with it.", "The elders may yet have to come and calm what is left. I said as much to you before. I say it again so that you never mistake one victory for a forest.", "The spirits gave me the marks on those machines. You gave the machines the only language the goblins understand. I think that is a fair division of the work." }, signoff = "In anger and in hope,\nSeereth Stonebreak" },
  [34] = { greeting = "Lucky $N,", body = { "Thirty! Thirty precious skulls, and every one of them beautiful! I count them at every change of the guard, in case one has rolled off somewhere. None has. They are very well behaved.", "I keep them out of sight, where Darthalia can't see them. She feels a Deathguard on duty ought to be guarding. I am. I guard them most carefully.", "Nothing ever happens at this post. While you were out in Hillsbrad having the time of your life, I was so jealous I could have fallen to pieces, which at my age is a real risk.", "I do hope you will stop at the gate when you pass, if only so I can thank you again." }, signoff = "Your devoted Deathguard,\nSamsa\nTarren Mill" },
  [35] = { greeting = "$N,", body = { "The harbor's open. Ships in, ships out, and not one crew watching the hills while it ties up. That's your doing.", "I'll tell you what I told Valstag. A siege engine is a patient thing. It sits in the hills and waits for you to get comfortable. Nek'rosh had his waiting for us, and you put a bit of tinder to every one of them. I watched the smoke from the keep wall and didn't say a word for a good while.", "The Dragonmaw aren't done. They'll lick their wounds in those hills a long time, and I'm watching. But they'll do it looking at a harbor that's still standing.", "A $R of merit, I called you. I'd call you that again in front of anyone." }, signoff = "Captain Stoutfist\nMenethil Harbor" },
  [36] = { greeting = "$N,", body = { "I walk to City Hall every morning past walls the Stonemasons raised after the war. Edwin set some of those stones himself. I used to point them out to visitors. I have stopped.", "You carried his unsent letter to me, and then followed it through the Stockade and beyond. I have heard that Lord Lescovar was found dead. I have not asked how, and I will not. I am grateful. I say it first, because the rest is harder to say.", "When the nobles refused to pay us, some of us were offered posts. I took mine. Edwin refused his, out of loyalty to the others, and swore revenge. I told you he did not care who he hurt, and that I was not sure I could blame him. I have not changed my mind about either.", "The city stands, and I keep its plans. Some mornings that feels like an answer to him, and some mornings it feels like the post he would not take." }, signoff = "Baros Alexston\nCity Architect" },
  [37] = { greeting = "$N,", body = { "I went back to the farm. It is the first time since that night. The barn still stands, and so does the old stump where the book was buried. I stood there a long while. Then I came back to my camp, and I slept.", "Morbent Fel is beaten. The dark riders are not, and I will not pretend otherwise. But a small piece of what I had stopped hoping for has come to pass, by your hand and by that blade from Stormwind.", "I know who Jitters is now. He watched my family die and could do nothing, and he wrote it all down because he could not carry it alone. I find I cannot hate a man for that. I am trying not to.", "Perhaps one day fate may bring you back to me. I mean it as I did then." }, signoff = "Sven Yorgen" },
  [38] = { greeting = "$N,", body = { "I laid the cards for Alyssa again. Death did not come up. What came up was a card I had not seen in a long while, a plain one, of no importance at all. It means an ordinary day. I sat and looked at it until my tea went cold.", "You followed a name out of my trance to the registry, to Moonbrook and Goldshire and Stormwind and back again, and every door you knocked on opened onto something older and worse. I sent you down that road. I am sorry for some of what you found at the end of it.", "The forest is still dark. The cards say so, and they are rarely wrong about Duskwood. But there is one shadow less over this house.", "Alyssa does not know how near it came, and I mean to keep it that way." }, signoff = "Madame Eva" },
  [39] = { greeting = "$N,", body = { "I am writing from Nijel's Point, with my bags packed for Darnassus. Vahlarriel says I may go when I am ready. I keep finding small reasons not to be ready yet.", "I thanked you for my brother's death. I have thought about that more than about anything the orcs did to me. I meant it, and I did not mean it, and both are still true. If it had not been your hand, it would have been one of my people's. That is a cold comfort, but it is the one I have.", "My father will ask what Tyranis wanted out here. I will tell him the truth: knowledge, more than was good for him, more than our people allow. I will not tell him how it ended.", "You brought me out of that fortress and let me walk it on my own feet. That part I will remember best." }, signoff = "Dalinda Malem" },
  [40] = { greeting = "$N,", body = { "Quae says I worry too much. Quae is right, and it's never once stopped me. So now that I know my two troublemakers are alive, I've found someone new to worry about. You.", "I've been reading what Kin brought out of that farm. At night, which is a bad habit, because it is not the kind of reading that helps a man sleep. Whatever Jorell is brewing out there, I'd bet my boots it has something to do with Stanley.", "My cousin still won't talk about that dog. I don't blame him.", "Anyway. Eat something hot, keep your back to a wall, and drink less than Kin does." }, signoff = "Phin Odelic\nSouthshore" },
  [41] = { greeting = "Dear valued customer,", body = { "Regarding your recent inquiry. The wheel you were looking for left Menethil by ship well before you started asking, as you found out in Menethil. Our friend at the harbor sends his regards and says he misses the excitement, which he asked me not to repeat, so I'll pretend I didn't write it.", "The rest of the order is with our friends in Theramore now, and they are careful people. Whether the wheel turns up again is out of my hands.", "I will say one thing plainly. You did more of the footwork than I paid for, and not a word of it has reached my shop from anyone but you. I've noticed. I notice most things." }, signoff = "With thanks for your custom,\nElling Trias\nTrias' Cheese, Trade District" },
  [42] = { greeting = "$N,", body = { "I sent Caldwell out to Lost Point, as I said I would. The marsh is not so big and trackless that a man can hide in it forever, though Reethe seems set on testing that.", "Jim still smiles at everyone. I stop and talk with him when I can. He speaks of the inn as though it were still standing out on the road, and I let him.", "It's never good news when a guard's badge is brought to me. Reethe's was the worst kind: a man so loyal to the old admiral that he turned his back on his oath, then too reckless even for the deserters he ran with. They call us the traitors. I'll grant them the irony.", "Balos Jacken asked you to forget you ever bumped into them. Please don't." }, signoff = "Captain Garran Vimes\nTheramore" },
  [43] = { greeting = "$N,", body = { "I'm the magistrate of a fishing town. I settle quarrels over nets and boundary stones, and now and then a drunk who has mistaken someone else's door for his own. I wasn't made for names like the Argus Wake.", "Dibbs has been through every book he owns looking for it, and found nothing.", "You dealt with the mages in the Uplands, and the Syndicate is the poorer for it. I wish that were the end. But whoever Nagaz served is still out there, further off than Alterac, and I am a man who likes to know where his worries live.", "So I look north in the evenings, where I used to look at the water. Thank you for bringing me what I did not want to know. Better me than no one." }, signoff = "Magistrate Henry Maleb\nSouthshore" },
  [44] = { greeting = "$N,", body = { "The tablet is with the king's mages, under more locks than I have keys for. What they learn from it is theirs to say. What I can say is that it never reached Shadowforge hands, and that it was Hammertoe's dream long before it was anyone's business.", "Karnik tells me he has spoken with Hammertoe's spirit. I am an advisor, not a priest, and I do not know what to make of that. But he says Hammertoe is content, and I have decided to believe him.", "Och. A dwarf who spent his life looking for where our people came from, and the last of it making sure the wrong hands never found it first. I'd not have done half so well, in his place or in yours.", "That is a life worth an advisor's letter, and you are the reason it was not wasted." }, signoff = "Advisor Belgrum\nIronforge" },
  [45] = { greeting = "$N,", body = { "You brought the Mind's Eye out of Mai'Zoth's hands, and the first thing I decided was not to look into it. A man who sets out to learn whether a thing can be used for good should not begin by letting it use him.", "It is wrapped and put away. I pray beside it, and I read what others have written of such things. If there is any good in it, I will find it. If there is not, it will be destroyed, and I will not grieve.", "I think often of Colonel Kurzen as he was, a great and noble man. The legends, the fetishes, all of it pointed to one truth: what broke him came from outside him. That is a comfort, and also a warning. It could have been any of us.", "May your strength never fade, $N." }, signoff = "Brother Nimetz\nRebel Camp" },
  [46] = { greeting = "$N,", body = { "How's the wee one? I've been wondering, and an old animal handler is allowed to wonder.", "A few things worth saying twice, what with the egg going off early. Sprite darters eat meat and greens both, so don't let anyone tell ye otherwise. Raw flanks, mind, and plenty of them.", "Kids, eh? One minute ye're running an egg halfway across the world with an hour to spare, and the next ye're a parent. Kinda.", "Haha. Look after yerself, and the wee one too, if ye kept it." }, signoff = "Agnar Beastamer\nAerie Peak" },
  [47] = { greeting = "$N,", body = { "Sharpbeak flew with the whole wing for the first time. He was too far out on the left and too proud of himself by half, and his mother brought him back into line twice. It was the finest thing I've seen from this peak in years.", "I sent word to Thadius at Nethergarde, for his part in it. He went off after darker knowledge long ago, and there are some here who still won't say his name. But it was his sight that found the lad, and in his heart he's a Wildhammer yet.", "The riders are making a song of it. It's not a good song. Wildhammer songs never are, the first year. They'll sing it anyway, for a long, long time, and your name's in every verse they've got so far." }, signoff = "Gryphon Master Talonaxe\nAerie Peak" },
  [48] = { greeting = "$N,", body = { "Emma Felstone writing. I've taken to signing it again, after all these years. It feels like a coat I left at somebody's house.", "I've been through everything Janice sent. Old letters. A recipe of Mother's I'd forgotten. The deed to the farm, of all things, as if I'd ever go back there. She always did pack as though she was moving in for good.", "I called you a grave-robber. I'll say I'm sorry once, plain, and then we'll not speak of it again. I'm sorry.", "If that charm did what I hoped, then she's resting, and not waiting on a delivery any more. If it didn't, don't tell me. I'd rather think it did." }, signoff = "Emma Felstone" },
  [49] = { greeting = "$N,", body = { "I do not understand why the Warchief wants so small a thing. A little chain, a little stone. I have seen warriors die for less, and for more, and I do not know which this is. I sent it on to Orgrimmar all the same, sewn into a rider's pack. I follow him. That has been enough for me so far, and it is enough now.", "Gol'dir told you he would make his own way once his business was settled, and I believe him. He is an orc of his word.", "As for the girl, I hope she has gone somewhere far from that manor. She was held there against her will, as our warriors were held at Durnholde. I am glad no one hurt her." }, signoff = "Krusk\nTarren Mill" },
  [50] = { greeting = "$N,", body = { "Another young one stood on the planks above the canyon and could not make the leap. I did not push. Faith that is pushed is not faith.", "I told the young one what I told you: the spirit, the body, the mind. You were tested in all three, and none of us made it easy. Parqual thought you were a fraud. Braug thought you might forget your reading. I only ever thought you would leap.", "You came to my home, and you came back changed. You came back balanced, and that is rarer than strength.", "Keep the balance." }, signoff = "Dorn" },
  [51] = { greeting = "$N,", body = { "A clumsy ogre kept himself out of the Dark Lady's reach for as long as he did, with nothing but a crown. I find that more unsettling than if it had been made of gold. Great power ought at least to have the decency to look the part.", "The crown has been delivered. I carried it to the Dark Lady myself, and I confess I held it a little away from me, as one carries something that might bite.", "She has heard of your part in it. I saw to that, as I said I would. Your name has been spoken in the Royal Quarter, which is more than most of the living can say." }, signoff = "Sharlindra" },
  [52] = { greeting = "$N,", body = { "You will forgive the length of this letter. Among my people a long sentence is taken either for a sign of genius or for a symptom of illness, and I have elected to be thought a genius.", "Mok'Morokk fled like a frightened child, and though he has since crept back to sulk among us, nobody in Brackenwall has forgotten it. The clan now deliberates upon his successor. Ogres deliberate in the manner of a rockslide: slowly, loudly, and with injuries. Tharg would serve admirably, were he younger and less broken.", "Meanwhile Onyxia's brood remains to the south, and I remain the only one in Brackenwall concerned with why. Your work among the eggs has bought us time. I intend to spend it wisely, which in this village makes me something of an eccentric." }, signoff = "With profound regard,\nDraz'Zilb" },
  [53] = { greeting = "$N,", body = { "The scholars have the pendant, and they are slow, which is how scholars ought to be. I have looked at it myself many times. Humans put more of themselves into a jewel than an orc puts into a sword.", "What I keep coming back to is the spy who took it. He watched Theramore for weeks, alone, and took the pendant on his final night, and a crab-man killed him on his way home. He did not finish his mission. You finished it for him. If spirits rest for such things, his should.", "A far seer learns to wait, and I will wait on the pendant for as long as it asks. Our spy did not have that luxury. I am glad he had you." }, signoff = "Zor Lonetree" },
  [54] = { greeting = "$N,", body = { "The raptor's guile wore off, as I knew it would. Then Gor'mul and I talked, the way I had hoped we might.", "He listened. He did not smile, and I did not ask him to. He asked whether the young Warchief truly wears Orgrim's armor and carries his hammer, and I told him yes. He was quiet a long while after that. Then he asked what the shamans can do now, and I showed him a little, and he did not throw it on the ground.", "That is not a warrior returned. But it is a warrior who asked a question, and in all the years he wandered alone, I do not think he asked anyone anything.", "You brought him some of the way back, $N, and the rest of the way is his." }, signoff = "Tor'gan\nHammerfall" },
  [55] = { greeting = "$N,", body = { "Trol'kalar is on its way to Nimboya at Grom'gol, wrapped in three cloths and carried by two of our fastest, because neither would let the other carry it alone.", "You know what the name means, mon. Troll slayer. For generations the men of Strom and Arathor carried it against my people, and our grandfathers' grandfathers learned to run at the sight of it. Now a troll has held it. I have held it. My hands shook, and I am not ashamed to say so.", "It will be wanted where our people fight, in the steamy forests of Zul'Gurub. Whether it remembers whose side it was made for, I cannot say.", "That it is in our hands at all is your doing, $N." }, signoff = "Zengu\nHammerfall" },
  [56] = { greeting = "$N,", body = { "The chief sent me across the sea to find his youngest son, and I will carry him home myself. Not as he left. In a gem no bigger than my fist, himself, free of Zanzil at last. It is more than I dared hope when I was counting Bloodscalp heads by the cauldron.", "The Great Serpent spared him the headhunter's axe, and you spared him the rest. A soul held so long by another will not wake all at once. Darkspear know patience. We crossed a whole sea once, and came back for him.", "Our songs will carry your name, mon. The stone I will leave to the carvers." }, signoff = "Nimboya\nGrom'gol Base Camp" },
  [57] = { greeting = "$C,", body = { "The fetishes are ash. I burned them myself at the edge of the Pool of Tears, and stood upwind. Whatever was in them took a long time to stop smoking.", "I keep thinking about that exile in the Hinterlands. He looked at his high priest's prophecy and said what he saw, and they wrote his sentence in blood on dried flesh and sent him to live among the Witherbark. Every army I have served in had a man like that. Most of them were right.", "Jammal'an still believes his god will make the Atal'ai immortal, and the green dragons watch the water for the day he tries." }, signoff = "Fel'zerul\nStonard" },
  [58] = { greeting = "$N,", body = { "The camp holds, and the Woodpaw come at it less, or so my sentries say. For years I took them for simple savages. Your map showed me otherwise. They were fighting on two fronts, and the one to the south was the one wearing them down. Something was pushing them north, and we were standing in the way.", "I have studied the glands you cut from Stinglasher until I could draw them from memory. Whatever lives in the Writhing Deep is organized, and patient, and closer than I like. It is my charge to see that we hold long enough to learn from it.", "For the first time in my life I pity a gnoll, and I would rather have gone on hating them." }, signoff = "Hadoken Swiftstrider\nCamp Mojache" },
  [59] = { greeting = "$N,", body = { "Hah! The vessel is ready, mon, and the materials you brought are better than I asked for. Splintered treant, giant's minerals, owlbeast sinew, all those little metal fragments. I sorted every piece myself, by smell.", "Neeru says he was satisfied with the head. A good customer, that one. He asks no questions, and he pays in herbs.", "What the muisek and the vessel make together is my business, and the spirits'. But I will tell you this much. When I put the last fragment in, the whole hut went quiet, the way a jungle goes quiet when something big is listening.", "You have good hands for gathering, $N, and a witch doctor always notices hands." }, signoff = "Witch Doctor Uzer'i\nCamp Mojache" },
  [60] = { greeting = "$N,", body = { "You worked hard in that snow. Four kinds of wildkin, each worse than the last, and you went through all of them.", "I have only ever seen Winterspring from the mouth of the Timbermaw tunnels, white and quiet. You have seen more of it than I have. If our roads cross, I would like to hear what those caves in the south looked like.", "What kind of secret drives its own guardians mad? I have turned that over every night since the runners came back. Whatever the night elves left out there was not left for us, and that is exactly why we must know it." }, signoff = "Trull Failbane\nBloodvenom Post" },
  [61] = { greeting = "$N,", body = { "Dare I say it again? A triumph! I have said it to everyone at the Bulwark who would stand still for it.", "I do enjoy a plan that works, and ours worked three times over. I hear the Crusade found our banner and went straight at the Scourge, exactly as hoped. The towers lit up on my priests' trackers like beacons on a map. And then you walked into Andorhal and brought me a shard of Araj's phylactery, which is the one part no plan of mine can take the credit for.", "The Scourge will not give up Andorhal for one fallen lich, and I would not insult you by pretending they will. But they will remember who set the Crusade on them, who marked their towers, and who walked in after." }, signoff = "High Executor Derrington\nThe Bulwark" },
  [62] = { greeting = "$N,", body = { "I am still Payson. I want that understood before anything else. I took the name after I woke into this glorious unlife, and a parcel from the dead does not change my mind.", "I called you a vulture. You were not one, as it turned out, and I find I mind being wrong less than I expected.", "But I kept what she sent. All of it. They are in a box under the cockroach crates, where no one will think to look, which is rather the point." }, signoff = "Jeremiah Payson\nCockroach Vendor" },
  [63] = { greeting = "$N,", body = { "Still the eighteenth pilot! I know. I'm as surprised as you are.", "The booster went off exactly the way Shreev said it would, which is to say all at once. Course record? Smashed it. Also two crates and most of my eyebrows. The eyebrows are growing back.", "I wanted to watch the gnomes watch me. Didn't. Too fast. That's the trouble with going to eleven: you miss the scenery.", "Pozzik is already tweaking the new regulator and muttering about safety.", "Thanks for all the running around, $N. I was busy going fast." }, signoff = "Razzeric\nThe Shimmering Flats" },
  [64] = { greeting = "$N,", body = { "A brief note, as I am in the middle of something. I am always in the middle of something.", "The bracers of rock binding have been invaluable. Two of them, at least. Servo has misplaced the other three, which is exactly why I asked you for five, which rather proves the method.", "The shackles are coming along. When they are done, a mage will be able to bind elementals of a strength nobody has bound before, assuming the coefficient behaves, which it will, now that I have accounted for the sand.", "Lucien tells me he made you something from the stones you had left over. I would have done so myself, of course, had I thought of it, which I did not, because I was thinking about the shackles." }, signoff = "Gratefully, and in a hurry,\nLotwil Veriatus" },
  [65] = { greeting = "$N,", body = { "The earth has your name in its mouth now. It is a good name.", "You brought down Khan Hratha. You brought down Khan Jehn. The Magram are already weak. I can still hear their bellies grumble when the wind is right. I laugh every time.", "The red crystal sits warm in my hands at night. My magic is strong now, stronger than any Khan believed. They trusted their strength. They did not listen to the earth. The earth remembers who did not listen.", "Your name is spoken at our fires already. The earth knows it, and I will be listening." }, signoff = "Uthek the Wise" },
  [66] = { greeting = "$N,", body = { "Between friends, then.", "The last batch went out to the flats, and I am told the pit crews were very quiet for a day or two afterwards. Meanwhile a good many people in Booty Bay seem to owe me a drink, and I have stopped paying for my own.", "Zanzil's mixture does strange things to yeast. Strange things to people, too, but yeast is my business, and I would keep it that way if I were you.", "Here is what I like about you. You carried a sinister scheme from Booty Bay to the flats and back, and not once did you ask what it was for. I paid you a little extra for that at the time. This letter is not payment. Think of it as a compliment, from a man who does not give them away." }, signoff = "Crank Fizzlebub\nBooty Bay" },
  [67] = { greeting = "$N,", body = { "Millions! Well. Thousands, nearly. Well, a very encouraging number of hundreds, and climbing!", "The fabulous Noggenfogger Elixir is selling better than anything in Gadgetzan that isn't water. Customers come back for more, which is the sign of a quality product. Some of them come back a little smaller, or a little bonier, or floating down from somewhere, but they come back, and that's what counts.", "Sprinkle keeps telling people I owe her a favor. Funny woman. The powder was her idea, sure, but the genius was in the stirring.", "You were there at the very beginning, $N, when it tasted like the inside of a dew gland, and I'll remember it when I'm famous." }, signoff = "Marin Noggenfogger\nGadgetzan" },
  [68] = { greeting = "$N,", body = { "It keeps coming back in pieces. A smell of salt. A wide field I think I grew up beside. A song somebody hummed while they sharpened blades. None of it in order, and none of it very useful, but all of it mine.", "The Golden Flame is going home, where it can be kept safe. I remember the way now. That's new.", "I gave you some advice once: it's dangerous to go alone. I'd have done well to take it myself.", "Without you I'd still be wandering this crater asking strangers my own name." }, signoff = "Linken\nMarshal's Refuge" },
  [69] = { greeting = "$N,", body = { "I watched you, you know. When the last brazier went dark in Shadow Hold, my spells could see again, and the first thing they showed me was you, standing in the smoke. I have scried a great many things in my life. I do not think I have ever been so glad to see one.", "Islen sent her regards with the water, and a warning I have not stopped turning over: that what I am tackling is larger than I know, and that I will find out soon enough. She is rarely wrong. The Council was struck at its head in Jaedenar, but a serpent like that has more than one.", "Felwood is still sick, and it will be sick a long while yet. But it is a little less sick in one dark corner, and the Earthmother sees that, even where no one else does." }, signoff = "Earthmother keep you,\nGreta Mosshoof\nEmerald Sanctuary" },
  [70] = { greeting = "$N,", body = { "For as long as I've known them, my friends have been the clever ones. Legacki, Sprinkle and her cooking, Quixxil and whatever it is Quixxil does. Mine were the ideas that got laughed at, so I kept them in my pocket.", "Not any more! The yeti is home again, a little scorched in one ear, and every time I look at it I think: I made that. A whole yeti. From a drawing.", "They all wrote back, by the way. I won't tell you what they said, since you were there for most of it. But two of them asked how it works, and that is the part I keep reading over.", "You carried a mechanical yeti halfway across the world for me, $N. Nobody has ever done anything that silly for my sake. Thank you." }, signoff = "Umi Rumplesnicker\nEverlook" },
  [71] = { greeting = "$N,", body = { "I have not slept well since you brought me that book. The Annals of Darrowshire. My home, written down by someone who was not there, and then written further by something I do not understand.", "It says my brother Joseph turned. That he was corrupted, and betrayed the defenders, and that they died for it. I was one of the defenders. I lived. Until I read it, I did not know who had betrayed us.", "The skull and the broken sword are locked away. I do not like what I feel when I touch them, so I do not touch them.", "Joseph had a daughter. I have not let myself think of her in years." }, signoff = "Carlin Redpath\nLight's Hope Chapel" },
  [72] = { greeting = "$N,", body = { "My son told you of his dream, that I stood beside him in the Order at last. He wanted it to end.", "I dream now. The same dream, I think. I stand beside him. He is a boy with a toy hammer, and then he is a man in his armor, and then he is gone. I wake before the end. The Light is merciful in that much.", "The Order is reborn. I did not want to take it up like this. But Taelan threw its standard down once, and you carried it back to him, and I will not let it fall a second time." }, signoff = "Tirion Fordring" },
  [73] = { greeting = "$N,", body = { "I am told that your kind, when it is grateful, writes. Marks on a thin skin, folded and carried from hand to hand. It is a slow way to say what a tide says at once. But you brought us the hands of four captains of fire, and so I will try your way.", "I do not understand how your kind measures gratitude. I have watched mortals for a long time, and I have seen them thank each other for very small things: a door held, a cup filled. You did not do a small thing. I do not know how large a letter must be, among you, for a thing that large.", "This one will have to do. The war goes on. But word of you has gone through the chambers of the Waterlords." }, signoff = "Duke Hydraxis" },
}
-- (the places Classic Era's client names otherwise, swapped in there)
ns.classicNames = {  }
